-- Placement journey reports: Placement Pipeline (broker slips and placement slips by status and age) and Market Response
-- (offers per insurer, response rate and hit ratio). Queries: src/modules/reports/queries.js (placementPipeline, marketResponse).
INSERT INTO app_settings(key, value, "group", label, type) VALUES
 ('reports.placement_age_buckets', '[7,14,30,60]'::jsonb, 'reports', 'Placement pipeline ageing buckets (days since the slip was created)', 'json'),
 ('reports.placement_open_statuses', '["draft","submitted","responses-in","sent","bound","declined"]'::jsonb, 'reports', 'Broker slip / placement slip statuses counted as open in the placement pipeline', 'json')
ON CONFLICT (key) DO NOTHING;

