  '[{"key":"slipType","label":"Slip","type":"text"},{"key":"slipNumber","label":"Slip No.","type":"text"},{"key":"createdDate","label":"Created","type":"date"},{"key":"status","label":"Status","type":"text"},{"key":"client","label":"Client / Insured","type":"text"},{"key":"product","label":"Product","type":"text"},{"key":"lob","label":"LOB","type":"text"},{"key":"insurer","label":"Lead Insurer","type":"text"},{"key":"insurers","label":"Insurers","type":"integer","total":false},{"key":"agent","label":"Agent","type":"text"},{"key":"sumInsured","label":"Sum Insured","type":"money"},{"key":"premium","label":"Premium (best offer / gross)","type":"money"},{"key":"ageDays","label":"Age (days)","type":"integer","total":false},{"key":"ageBucket","label":"Age Bucket","type":"text"}]'::jsonb,
  ARRAY['sales','underwriting','customer-services']::text[], 95),
 ('market-response', 'Market Response', 'operational', 'Insurers approached on broker slips in the period: offers, declines, pending, response rate, average response days, offers taken and hit ratio (offers taken / offers made).', 'Operations > Broker Slips > Reports', 'marketResponse',
  '{"type":"object","required":["ReportCriteria"],"properties":{"ReportCriteria":{"type":"string","title":"Report Criteria","enum":["Overall","Line of Business","Agent"],"default":"Overall"},"FromDate":{"type":"string","format":"date","title":"From Date"},"ToDate":{"type":"string","format":"date","title":"To Date"},"Agent":{"type":"string","title":"Agent","description":"id, code or name","x-options":"users"},"Company":{"type":"string","title":"Company (insurer)","description":"id, code or name","x-options":"insurance_companies"},"Branch":{"type":"string","title":"Branch","description":"id, code or name","x-options":"branches"},"Product":{"type":"string","title":"Product","description":"id, code or name","x-options":"products"},"format":{"type":"string","enum":["csv","xlsx","pdf"],"default":"xlsx","title":"File format (generate only)"},"period":{"type":"string","enum":["today","yesterday","last-7-days","last-30-days","month-to-date","previous-month","year-to-date"],"title":"Relative period (schedules; used when no dates are given)"}}}'::jsonb,
